export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossedHeight = launchSpeed * t - 0.5 * gravity * t * t;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;

  let dropHeight = apexHeight;
  let dropVelocity = 0;
  let dropAcceleration = 0;

  if (t >= apexTime) {
    const dt = t - apexTime;
    dropHeight = apexHeight - 0.5 * gravity * dt * dt;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
  }

  const scaleY = 120;
  const baseY = 320;

  const tossX = 200;
  const dropX = 440;

  const tossY = baseY - tossedHeight * scaleY;
  const dropY = baseY - dropHeight * scaleY;

  let tossState = "At launch";
  if (t < apexTime - 0.05) tossState = "Rising";
  else if (Math.abs(t - apexTime) <= 0.05) tossState = "At the top";
  else if (t > apexTime && tossedHeight > 0.05) tossState = "Falling";
  else if (t >= apexTime) tossState = "At launch height";

  let dropState = "Held in place";
  if (Math.abs(t - apexTime) <= 0.05) dropState = "Just released";
  else if (t > apexTime && dropHeight > 0.05) dropState = "Falling together";
  else if (t > apexTime) dropState = "At launch height";

  const objects = [];

  objects.push(...sdk.panel({ x: 60, y: 50, w: 240, h: 320, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: 50, w: 240, h: 320, title: "Drop lane", state: dropState, id: "lane.drop" }));

  objects.push(sdk.axis("axis.toss", { x: tossX, y: baseY, length: 260, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: dropX, y: baseY, length: 260, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));

  objects.push(sdk.circle("ball.toss", tossX, tossY, 26, { role: "output" }));
  objects.push(sdk.circle("ball.drop", dropX, dropY, 26, { role: "output" }));

  if (t < apexTime) {
    objects.push(sdk.gate("gate", dropX, baseY - apexHeight * scaleY, { open: false, label: "Gate" }));
  } else {
    objects.push(sdk.gate("gate", dropX, baseY - apexHeight * scaleY, { open: true, label: "Gate" }));
  }

  objects.push(...sdk.vector("vec.v.toss", { x: tossX - 20, y: tossY }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: tossX + 20, y: tossY }, { value: tossedAcceleration, direction: "up" }, { scale: 5, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX - 20, y: dropY }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: dropX + 20, y: dropY }, { value: dropAcceleration, direction: "up" }, { scale: 5, label: "a" }));

  objects.push(...sdk.callout(tossX + 45, tossY - 20, [
    `v: ${sdk.format(tossedVelocity, 2)} m/s`,
    `a: ${sdk.format(tossedAcceleration, 1)} m/s^2`
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(dropX + 45, dropY - 20, [
    `v: ${sdk.format(dropVelocity, 2)} m/s`,
    `a: ${sdk.format(dropAcceleration, 1)} m/s^2`
  ], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
